import React, { useState } from 'react';
import { Eye, EyeOff, X, Mail, Lock } from 'lucide-react';
import '../styles/SignIn.css';

export default function SignIn({ isOpen, onClose }) {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const [isLogin, setIsLogin] = useState(true);
  const [signUpData, setSignUpData] = useState({
    fullName: '',
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [showSignUpPassword, setShowSignUpPassword] = useState(false);
  const [showSignUpConfirmPassword, setShowSignUpConfirmPassword] = useState(false);

  const handleLoginChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSignUpChange = (e) => {
    const { name, value } = e.target;
    setSignUpData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleLoginSubmit = (e) => {
    e.preventDefault();
    console.log('Login data:', formData);
    // TODO: Add API call here
  };

  const handleSignUpSubmit = (e) => {
    e.preventDefault();
    if (signUpData.password !== signUpData.confirmPassword) {
      alert('Passwords do not match!');
      return;
    }
    console.log('Sign up data:', signUpData);
    // TODO: Add API call here
  };

  if (!isOpen) return null;

  return (
    <div className="signin-modal-overlay" onClick={onClose}>
      <div className="signin-modal-content" onClick={(e) => e.stopPropagation()}>
        <button className="signin-close-btn" onClick={onClose}>
          <X size={24} />
        </button>

        {isLogin ? (
          // LOGIN FORM
          <div className="signin-container">
            <h1 className="login-title">Log in to continue your learning journey</h1>
            <p className="login-subtitle">Welcome back! Please enter your details to access your account.</p>

            <form onSubmit={handleLoginSubmit} className="login-form">
              <div className="input-field-icon">
                <Mail size={20} className="field-icon" />
                <input
                  type="email"
                  name="email"
                  placeholder="Email"
                  value={formData.email}
                  onChange={handleLoginChange}
                  required
                />
              </div>

              <div className="input-field-icon">
                <Lock size={20} className="field-icon" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  name="password"
                  placeholder="Password"
                  value={formData.password}
                  onChange={handleLoginChange}
                  required
                />
                <button
                  type="button"
                  className="password-toggle-icon"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>

              <a href="#" className="forgot-password-link">Forgot password?</a>

              <button type="submit" className="continue-btn">Continue</button>
            </form>

            <div className="or-divider">
              <span>Or</span>
            </div>

            <div className="signup-prompt">
              <p>Don't have an account? <button className="signup-link" onClick={() => setIsLogin(false)}>Sign up</button></p>
            </div>
          </div>
        ) : (
          // SIGNUP FORM
          <div className="signin-container">
            <h1 className="login-title">Create your account</h1>
            <p className="login-subtitle">Join us and start your learning journey today.</p>

            <form onSubmit={handleSignUpSubmit} className="login-form">
              <div className="form-group">
                <label htmlFor="fullName">Full name</label>
                <input
                  type="text"
                  id="fullName"
                  name="fullName"
                  placeholder="Full name"
                  value={signUpData.fullName}
                  onChange={handleSignUpChange}
                  required
                />
              </div>

              <div className="form-group">
                <label htmlFor="signup-email">Email</label>
                <input
                  type="email"
                  id="signup-email"
                  name="email"
                  placeholder="Email"
                  value={signUpData.email}
                  onChange={handleSignUpChange}
                  required
                />
              </div>

              <div className="form-group">
                <label htmlFor="signup-password">Password</label>
                <div className="password-input-wrapper">
                  <input
                    type={showSignUpPassword ? 'text' : 'password'}
                    id="signup-password"
                    name="password"
                    placeholder="Password"
                    value={signUpData.password}
                    onChange={handleSignUpChange}
                    required
                  />
                  <button
                    type="button"
                    className="password-toggle"
                    onClick={() => setShowSignUpPassword(!showSignUpPassword)}
                  >
                    {showSignUpPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>

              <div className="form-group">
                <label htmlFor="confirm-password">Confirm password</label>
                <div className="password-input-wrapper">
                  <input
                    type={showSignUpConfirmPassword ? 'text' : 'password'}
                    id="confirm-password"
                    name="confirmPassword"
                    placeholder="Confirm password"
                    value={signUpData.confirmPassword}
                    onChange={handleSignUpChange}
                    required
                  />
                  <button
                    type="button"
                    className="password-toggle"
                    onClick={() => setShowSignUpConfirmPassword(!showSignUpConfirmPassword)}
                  >
                    {showSignUpConfirmPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>

              <button type="submit" className="continue-btn">Create Account</button>
            </form>

            <div className="or-divider">
              <span>Or</span>
            </div>

            <div className="signup-prompt">
              <p>Already have an account? <button className="signup-link" onClick={() => setIsLogin(true)}>Log in</button></p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
